public static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    // Check if the current position of the ByteBuffer is valid
    if (bb.position() + i > bb.limit()) {
        throw new IndexOutOfBoundsException("Index out of bounds: " + i);
    }

    // Initialize the number of bytes to decode
    int numBytes = 0;

    // Check the first byte to determine the number of bytes to decode
    byte firstByte = bb.get(i);
    if (firstByte < 0) {
        numBytes = 2;
    } else if (firstByte < 0b11000000) {
        numBytes = 1;
    } else if (firstByte < 0b11100000) {
        numBytes = 2;
    } else if (firstByte < 0b11110000) {
        numBytes = 3;
    } else {
        throw new IllegalArgumentException("Invalid UTF-8 sequence");
    }

    // Check if there are enough bytes to decode
    if (bb.remaining() < numBytes) {
        throw new IndexOutOfBoundsException("Not enough bytes to decode");
    }

    // Decode the bytes
    int codePoint = 0;
    for (int j = 0; j < numBytes; j++) {
        codePoint = (codePoint << 6) | (bb.get(i + j) & 0x3F);
    }

    // Append the decoded character to the StringBuffer
    sb.appendCodePoint(codePoint);

    // Return the index to the next unchecked character
    return i + numBytes;
}

