public void generateGraph(Graph<V,E> target, Map<String,V> resultMap) {
    // Create two sets of vertices, one for each side of the bipartite graph
    Set<V> leftSet = new HashSet<>();
    Set<V> rightSet = new HashSet<>();

    // Add vertices to the left set
    leftSet.addAll(resultMap.keySet());

    // Add vertices to the right set
    rightSet.addAll(resultMap.values());

    // Create edges between the vertices
    for (V leftVertex : leftSet) {
        for (V rightVertex : rightSet) {
            // Add an edge between the left and right vertices, if they are not already connected
            if (!target.containsEdgeBetween(leftVertex, rightVertex)) {
                E edge = new Edge<>(leftVertex, rightVertex);
                edge.setWeight(1);
                target.addEdge(edge);
            }
        }
    }
}

