public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {

    // Check if the genericType is parameterized
    if (genericType instanceof ParameterizedType) {
        ParameterizedType parameterizedType = (ParameterizedType) genericType;

        // Get the type arguments of the parameterizedType
        Type[] typeArguments = parameterizedType.getActualTypeArguments();

        // Create a Class array to store the resolved arguments
        Class<?>[] resolvedArguments = new Class<?>[typeArguments.length];

        // Loop through the type arguments
        for (int i = 0; i < typeArguments.length; i++) {
            Type typeArgument = typeArguments[i];

            // Check if the type argument is a type variable
            if (typeArgument instanceof TypeVariable) {
                // Get the type variable name
                String typeVariableName = ((TypeVariable) typeArgument).getName();

                // Check if the targetType has type variables
                if (targetType instanceof ParameterizedType) {
                    ParameterizedType parameterizedTargetType = (ParameterizedType) targetType;

                    // Get the type variables of the targetType
                    Type[] targetTypeVariables = parameterizedTargetType.getActualTypeArguments();

                    // Check if the type variable name is present in the targetType's type variables
                    for (Type targetTypeVariable : targetTypeVariables) {
                        if (targetTypeVariable.getTypeName().equals(typeVariableName)) {
                            // If it is present, get the type argument of the targetType's type variable
                            Type targetTypeArgument = targetTypeVariable.getActualTypeArgument();

                            // If the targetType argument is a class, add it to the resolved arguments array
                            if (targetTypeArgument instanceof Class) {
                                resolvedArguments[i] = (Class<?>) targetTypeArgument;
                            }

                            // If the targetType argument is a parameterized type, recursively resolve its type arguments
                            if (targetTypeArgument instanceof ParameterizedType) {
                                resolvedArguments[i] = resolveArguments((ParameterizedType) targetTypeArgument, targetType);
                            }
                        }
                    }
                }
            } else {
                // If the type argument is not a type variable, get its class
                resolvedArguments[i] = (Class<?>) typeArgument;
            }
        }

        // Return the resolved arguments
        return resolvedArguments;
    }

    // If the genericType is not parameterized, return null
    return null;
}

