                    for (Map.Entry<String, Object> doubleNestedEntry : doubleNestedField.entrySet()) {
                        String doubleNestedFieldName = doubleNestedEntry.getKey();
                        Object doubleNestedFieldValue = doubleNestedEntry.getValue();
                        inputFields.put(doubleNestedFieldName, new Field(doubleNestedFieldName, doubleNestedFieldValue));
                    }
                } else {
                    inputFields.put(nestedFieldName, new Field(nestedFieldName, nestedFieldValue));
                }
            }
        } else {
            inputFields.put(fieldName, new Field(fieldName, fieldValue));
        }
    }

    // check if the input mappings contain any fields that do not exist in the current index
    for (Field inputField : inputFields.values()) {
        if (!currentIndex.getFields().contains(inputField.getName())) {
            throw new IllegalArgumentException("Field '" + inputField.getName() + "' does not exist in the current index");
        }
    }

    // return the mappings with the fields that do not exist in the input mappings
    Mappings diffMappings = new Mappings();
    for (Field inputField : inputFields.values()) {
        if (!currentIndex.getFields().contains(inputField.getName())) {
            diffMappings.put(inputField.getName(), inputField.getType());
        }
    }
    return diffMappings;
}

