public static long compressTimeBucket(long timeBucket, int dayStep) {
  // Validate input parameters
  if (timeBucket <= 0 || dayStep <= 0) {
    throw new java.lang.IllegalArgumentException("Invalid input parameters.");
  }

  // Calculate the number of days to add to the time bucket
  int daysToAdd = (dayStep - (int)timeBucket.Mod(2).Add(dayStep)) % dayStep;

  // Add the calculated number of days to the time bucket to get the compressed time bucket
  long compressedTimeBucket = timeBucket.AddDays(daysToAdd).GetDate();

  return compressedTimeBucket;
}

public static long compressTimeBucket(long timeBucket, int dayStep) {
    return timeBucket - (timeBucket % dayStep);
}

public static long compressTimeBucket(long timeBucket, int dayStep) {
  int year = (int) (timeBucket / 10000);
  int month = (int) ((timeBucket % 10000) / 100);
  int day = (int) (timeBucket % 100);
  int newDay = (int) (day / dayStep) + (day % dayStep == 0 ? 0 : 1);
  long newTimeBucket = year * 10000 + month * 100 + newDay;
  return newTimeBucket;
}

@Override
public long compressTimeBucket(long timeBucket, int dayStep) {
    // Calculate the upper bound of the time bucket
    long upperBound = timeBucket - (timeBucket % dayStep);

    // If the time bucket is less than or equal to the upper bound, return the time bucket
    if (timeBucket <= upperBound) {
        return timeBucket;
    }

    // Calculate the lower bound of the time bucket
    long lowerBound = upperBound - dayStep;

    // If the time bucket is greater than or equal to the lower bound, return the lower bound
    if (timeBucket >= lowerBound) {
        return lowerBound;
    }

    // Otherwise, return the upper bound
    return upperBound;
}

public static long compressTimeBucket(long timeBucket, int dayStep) {
    // Calculate the new time bucket by subtracting the modulus of the current time bucket and the day step
    long newTimeBucket = timeBucket - (timeBucket % dayStep);
    return newTimeBucket;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    // Calculate the size of the string in UTF-8
    int size = 0;
    for (int i = index; i < len; i++) {
        char c = str.charAt(i);
        if (c <= 0x7F) {
            size += 1;
        } else if (c <= 0x7FF) {
            size += 2;
        } else if (c <= 0xFFFF) {
            size += 3;
        } else {
            size += 4;
        }
    }
    return size;
}

