    }

    // Iterate over the characters in the CharSequence and compute the size of the UTF-8 encoding
    int size = 0;
    for (int i = index; i < index + len; i++) {
        char c = str.charAt(i);
        size += getUTF8Size(c);
    }

    return size;
}

