    if (byteOffset < 0 || byteLength < 0 || byteOffset + byteLength > byteArrayValue.length) {
        throw new IllegalArgumentException("Invalid byte offset and length");
    }

    /* 2. Enlarge the byte vector if necessary */
    int requiredLength = byteOffset + byteLength;
    int currentLength = getSize();
    if (requiredLength > currentLength) {
        putElement(requiredLength - currentLength, (byte) 0);
    }

    /* 3. Put the bytes into the byte vector */
    int i = byteOffset;
    for (int j = 0; j < byteLength; j++) {
        putElement(i++, byteArrayValue[j]);
    }

    /* 4. Return the byte vector */
    return this;
}

