public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
    if (byteArrayValue == null) {
        throw new NullPointerException("byteArrayValue cannot be null");
    }
    if (byteOffset < 0 || byteOffset >= byteArrayValue.length) {
        throw new IndexOutOfBoundsException("byteOffset is out of range");
    }
    if (byteLength < 0 || byteLength > byteArrayValue.length - byteOffset) {
        throw new IndexOutOfBoundsException("byteLength is out of range");
    }
    ensureCapacity(byteLength);
    System.arraycopy(byteArrayValue, byteOffset, data, size, byteLength);
    size += byteLength;
    return this;
}

public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
    // Check if the byteArrayValue is null
    if (byteArrayValue == null) {
        // If it is null, throw an exception
        throw new NullPointerException("byteArrayValue cannot be null");
    }

    // Check if the byteOffset is valid
    if (byteOffset < 0 || byteOffset >= byteArrayValue.length) {
        // If it is not, throw an exception
        throw new IndexOutOfBoundsException("byteOffset must be non-negative and less than the length of byteArrayValue");
    }

    // Check if the byteLength is valid
    if (byteLength < 0 || byteLength > byteArrayValue.length - byteOffset) {
        // If it is not, throw an exception
        throw new IndexOutOfBoundsException("byteLength must be non-negative and less than or equal to the length of byteArrayValue minus the byteOffset");
    }

    // Copy the bytes from the input array to the internal array
    System.arraycopy(byteArrayValue, byteOffset, this.array, this.length, byteLength);

    // Increment the length of the internal array
    this.length += byteLength;

    // Return the modified byte vector
    return this;
}

