public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    if (str == null) {
        return lb;
    }
    final UTF8_CodeUnit_Order concatOrder = new UTF8_CodeUnit_Order();
    int numCodeUnits = concatOrder.getNumCodeUnits(str);
    int exceedingCodeUnits = numCodeUnits - session.getNumberOfAvailableCodeUnits();
    if (exceedingCodeUnits > 0) {
        int codeUnit = concatOrder.getCodeUnitAt(str, numCodeUnits - exceedingCodeUnits - 1);
        int numCThreeBytes = (exceedingCodeUnits + 1) / 2;
        int numCOneBute = exceedingCodeUnits % 2;
        if (numCThreeBytes > 0) {
            byte[] CThreeBytes = new byte[numCThreeBytes * 3];
            int i = 0;
            while (i < CThreeBytes.length) {
                CThreeBytes[i++] = (byte) (codeUnit >> 24);
                CThreeBytes[i++] = (byte) (codeUnit >> 16);
                CThreeBytes[i++] = (byte) (codeUnit >> 8);
                CThreeBytes[i++] = (byte) codeUnit;
            }
            lb.write(CThreeBytes);
        }
        if (numCOneBute > 0) {
            byte[] COneBute = new byte[numCOneBute];
            COneBute[0] = (byte) codeUnit;
            lb.write(COneBute);
        }
    } else {
        for (int i = 0; i < numCodeUnits; i++) {
            int codeUnit = concatOrder.getCodeUnitAt(str, i);
            lb.write((byte) (codeUnit >> 24));
            lb.write((byte) (codeUnit >> 16));
            lb.write((byte) (codeUnit >> 8));
            lb.write((byte) codeUnit);
        }
    }
    return lb;
}

