public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> pathSegments = new ArrayList<>();
    String[] segments = u.getPath().split("/");
    for (String segment : segments) {
        if (segment.isEmpty()) {
            continue;
        }
        if (decode) {
            PathSegmentImpl pathSegment = new PathSegmentImpl();
            pathSegment.original = segment;
            pathSegment.encodedValue = decode(segment);
            pathSegments.add(pathSegment);
        } else {
            pathSegments.add(new PathSegmentImpl(segment));
        }
    }
    return pathSegments;
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) throws URISyntaxException {
    List<PathSegmentImpl> segments = new ArrayList<>();

    String path = u.getPath();
    if (path.isEmpty()) {
        return Collections.emptyList();
    }

    String[] pathSegments = path.split("/");
    for (String pathSegment : pathSegments) {
        if (!pathSegment.isEmpty()) {
            PathSegmentImpl segment = new PathSegmentImpl(pathSegment, decode);
            segments.add(segment);
        }
    }

    return segments;
}

public static List<PathSegmentImpl> decodePath(URI uri, boolean decode) {
    String path = uri.getPath();
    List<String> segments = Arrays.asList(path.split("/"));
    List<PathSegmentImpl> pathSegments = new ArrayList<>();
    for (String segment : segments) {
        if (decode) {
            segment = URLDecoder.decode(segment, "UTF-8");
        }
        pathSegments.add(new PathSegmentImpl(segment));
    }
    return pathSegments;
}

