}

public static List<PathSegmentImpl> decodePath(URI u,boolean decode){
  // Return an empty list if the URI doesn't have a path
  if (u.getPath() == null) {
    return Collections.emptyList();
  }

  // Split the path into segments
  String[] segments = u.getPath().split("/");

  // Create a list to store the path segments
  List<PathSegmentImpl> pathSegments = new ArrayList<PathSegmentImpl>();

  // Iterate over the segments
  for (String segment : segments) {
    // Decode the segment if necessary
    if (decode) {
      segment = URLDecoder.decode(segment, "UTF-8");
    }

    // Add the segment to the list
    pathSegments.add(new PathSegmentImpl(segment));
  }

  // Return the list of path segments
  return pathSegments;
}

