private void pop(final String descriptor) {
    String[] typeTokens = descriptor.split("\\s*;\\s*");
    for (int i = 0; i < typeTokens.length; i++) {
        String typeToken = typeTokens[i];
        String typeName = typeToken.substring(typeToken.lastIndexOf('/') + 1);
        Object value = stack.pop();
        Type valueType = value.getClass();
        if (!typeName.equals(valueType.getName()) && !typeName.endsWith("[]")) {
            throw new RuntimeException("Incompatible types: expected " + typeName + ", got " + valueType.getName());
        }
    }
}

