private void enlarge(final int size) {
  // Handle case where vector is already sufficient
  if (size <= 0) {
    return;
  }

  // Handle case where size is negative
  if (size < 0) {
    throw new IllegalArgumentException("Size must be non-negative");
  }

  // Calculate the new capacity
  int newCapacity = capacity + size;

  // Handle case where capacity exceeds limit
  if (newCapacity > limit) {
    throw new IndexOutOfBoundsException("Enlarging beyond limit");
  }

  // Update capacity and size
  capacity = newCapacity;
}

