	/*
	 * The Math.abs() method returns the absolute value of a double value.
	 * It is used to compare two floating point values by converting them to positive values.
	 * The signum() method returns the sign of a double value as an int.
	 * The multiplyExact() method multiplies two int values and returns the result as an int.
	 */
	return Integer.signum(Math.abs(o1) - Math.abs(o2)) * Integer.multiplyExact(Math.abs(o1), Math.abs(o2));
}

