public final byte[] toByteArray() {
    // Check if the buffer(s) are empty
    if (isEmpty()) {
        return new byte[0];
    }

    // Get the total length of the buffer(s)
    int totalLength = 0;
    for (ByteBuffer buf : this) {
        totalLength += buf.remaining();
    }

    // Create a new byte array with the total length
    byte[] result = new byte[totalLength];

    // Copy the contents of the buffer(s) into the byte array
    int offset = 0;
    for (ByteBuffer buf : this) {
        int length = buf.remaining();
        buf.get(result, offset, length);
        offset += length;
    }

    return result;
}

