public static Object copyArrayGrow1(Object array, Class<?> newArrayComponentType) {
    if (array == null) {
        if (newArrayComponentType == null) {
            throw new NullPointerException("Array and newArrayComponentType cannot both be null");
        }
        return Array.newInstance(newArrayComponentType, 1);
    }
    int newSize = array.length + 1;
    Object newArray = Array.newInstance(array.getClass().getComponentType(), newSize);
    System.arraycopy(array, 0, newArray, 0, array.length);
    return newArray;
}

private static Object copyArrayGrow1(final Object array, final Class<?> newArrayComponentType) {
    if (array == null) {
        if (newArrayComponentType == null) {
            throw new IllegalArgumentException("Cannot create array of null type");
        } else {
            // Create a new array of size 1 with the specified component type
            return Array.newInstance(newArrayComponentType, 1);
        }
    } else {
        // Create a new array of size 1 greater than the input array
        return Arrays.copyOf(array, array.length + 1);
    }
}

