import org.apache.spark.sql.SparkSession

def removeUnusedNodes(sparkSession: SparkSession): Int = {
    // Get the list of active nodes from the database
    val activeNodeIds = sparkSession.read.parquet("active_nodes.parquet").as[Long].collect()

    // Get the list of all nodes in the Category tree
    val allNodeIds = sparkSession.read.parquet("category_tree.parquet").as[Long].collect()

    // Calculate the set of inactive nodes
    val inactiveNodeIds = allNodeIds.diff(activeNodeIds).toSet

    // Delete the inactive nodes from the Category tree
    sparkSession.sql(s"DELETE FROM category_tree WHERE nodeId IN (${inactiveNodeIds.mkString(",")})")

    // Return the number of inactive nodes deleted
    inactiveNodeIds.size
}

