public int addConstantNameAndType(final String name, final String descriptor) {
    if (constantPoolMap.containsKey(name + descriptor)) {
        return constantPoolMap.get(name + descriptor);
    } else {
        int index = constantPoolSize;
        constantPoolMap.put(name + descriptor, index);
        constantPool.add(new Symbol(CONSTANT_NameAndType_info, name, descriptor));
        constantPoolSize++;
        return index;
    }
}

int addConstantNameAndType(final String name, final String descriptor) {
    int index = -1;
    for (int i = 0; i < constantPool.size(); i++) {
        ConstantInfo constant = constantPool.get(i);
        if (constant instanceof ConstantNameAndType) {
            ConstantNameAndType nameAndType = (ConstantNameAndType) constant;
            if (nameAndType.getName().equals(name) && nameAndType.getDescriptor().equals(descriptor)) {
                index = i;
                break;
            }
        }
    }
    if (index == -1) {
        constantPool.add(new ConstantNameAndType(name, descriptor));
        index = constantPool.size() - 1;
    }
    return index;
}

public int addConstantNameAndType(final String name, final String descriptor) {
    if (!constantPool.containsNameAndType(name, descriptor)) {
        constantPool.addNameAndType(name, descriptor);
    }
    return getConstantIndex(Const.CONSTANT_NameAndType, name, descriptor);
}

public Symbol addConstantNameAndType(String name, String descriptor) {
    // Check if the constant pool already contains a similar item
    for (int i = 0; i < constantPool.size(); i++) {
        Symbol symbol = constantPool.get(i);
        if (symbol.getName().equals(name) && symbol.getDescriptor().equals(descriptor)) {
            return symbol;
        }
    }

    // Create a new Symbol with the given value
    Symbol symbol = new Symbol(name, descriptor);
    constantPool.add(symbol);
    return symbol;
}

public int addConstantNameAndType(final String name, final String descriptor) {
    // Add the constant pool entry for the name and descriptor
    ConstantNameAndType_info constantNameAndType = new ConstantNameAndType_info(name, descriptor);
    int index = constantPool.addEntry(constantNameAndType);

    // Check if there is already a matching Symbol
    Symbol symbol = symbols.get(name);
    if (symbol != null && symbol.getDescriptors().contains(descriptor)) {
        // If there is already a matching Symbol, return it
        return symbol.getIndex();
    }

    // Otherwise, create a new Symbol and return its index
    symbol = new Symbol(name, descriptor);
    symbols.put(name, symbol);
    return symbol.getIndex();
}

