private String unescapeId(String input){
    // First, replace any escaped backslashes with single backslashes
    String output = input.replace("\\\\", "\\");

    // Next, replace any escaped backslashes with single backslashes
    output = output.replace("\\\"", "\"");

    return output;
}

private String unescapeId(String input) {
    // Create a new String builder to build the output
    StringBuilder output = new StringBuilder();

    // Iterate through the input string
    for (int i = 0; i < input.length(); i++) {
        // Get the current character
        char currentChar = input.charAt(i);

        // Check if the current character is a special character
        if (currentChar == '\\') {
            // If the current character is a backslash, check if the next character is also a backslash
            if (i + 1 < input.length() && input.charAt(i + 1) == '\\') {
                // If the next character is a backslash, skip over it and add a single backslash to the output
                i++;
                output.append('\\');
            } else {
                // If the next character is not a backslash, add the current character to the output
                output.append(currentChar);
            }
        } else {
            // If the current character is not a backslash, add it to the output
            output.append(currentChar);
        }
    }

    // Return the output string
    return output.toString();
}

public String unescapeId(String input){

    // Check if the input contains any escaped characters
    if(input.contains("\\")){
        // Replace the escaped backslash with regular backslash
        input = input.replace("\\", "\\\\");
    }
    if(input.contains("\"")){
        // Replace the escaped double quote with regular double quote
        input = input.replace("\\\"", "\"");
    }
    if(input.contains("'")){
        // Replace the escaped single quote with regular single quote
        input = input.replace("\\'", "\'");
    }

    return input;
}

