    Set<Integer> zeroBucket = bucketsByLabel.get(0);
    zeroBucket.addAll(minBucket);
    minBucket.clear();
    for (int label : labels) {
        if (label == minLabel) {
            labels.get(label).clear();
        }
    }
}

