    Set<Integer> verticesToMove = bucketsByLabel.get(minLabel);
    Set<Integer> verticesToClear = new HashSet<>(bucketsByLabel.get(0));
    verticesToClear.addAll(verticesToMove);
    bucketsByLabel.get(0).clear();
    bucketsByLabel.get(0).addAll(verticesToClear);
    labels.get(minLabel).update(0);
}

private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    Set<Integer> minBucket = bucketsByLabel.get(minLabel);
    for (int vertex : minBucket) {
        labels.set(vertex, 0);
    }
    bucketsByLabel.set(0, new HashSet<>(minBucket));
    bucketsByLabel.set(minLabel, new HashSet<>());
}

private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    // Move all vertices from the bucket with label minLabel to the bucket with label 0
    Set<Integer> verticesToMove = bucketsByLabel.get(minLabel);
    if (verticesToMove != null) {
        for (Integer vertex : verticesToMove) {
            bucketsByLabel.get(0).add(vertex);
        }
        bucketsByLabel.set(minLabel, null);
    }

    // Clear the bucket with label minLabel
    bucketsByLabel.get(minLabel).clear();

    // Update the labeling accordingly
    for (int i = 0; i < labels.size(); i++) {
        if (labels.get(i) == minLabel) {
            labels.set(i, 0);
        }
    }
}

private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    // Find the bucket with label minLabel and the bucket with label 0
    Set<Integer> fromBucket = bucketsByLabel.get(minLabel);
    Set<Integer> toBucket = bucketsByLabel.get(0);

    // Move all vertices from the bucket with label minLabel to the bucket with label 0
    toBucket.addAll(fromBucket);

    // Update the labeling of the vertices
    for (int vertex : fromBucket) {
        labels.set(vertex, 0);
    }

    // Clear the bucket with label minLabel
    fromBucket.clear();
}

