private Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds){
    List<Integer> suffixSum = new ArrayList<>();
    long sum = 0;
    for (int i = bounds.size() - 1; i >= 0; i--) {
        sum += bounds.get(i);
        suffixSum.add(sum);
    }
    return new Pair<>(suffixSum, sum);
}

private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    if (bounds == null || bounds.isEmpty()) {
        throw new IllegalArgumentException("Bounds list is empty");
    }

    int size = bounds.size();
    List<Integer> suffixSums = new ArrayList<>(size);
    long sum = 0;

    for (int i = 0; i < size; i++) {
        sum += bounds.get(i);
        suffixSums.add(sum);
    }

    return Pair.of(suffixSums, sum);
}

private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    List<Integer> suffixSums = new ArrayList<Integer>();
    long totalSum = 0;
    for (int i = 0; i < bounds.size(); i++) {
      suffixSums.add(bounds.get(i) + (i == 0 ? 0 : suffixSums.get(i - 1)));
      totalSum += bounds.get(i);
    }
    return Pair.of(suffixSums, totalSum);
  }

