  List<Pair<List<Pair<Integer,Integer>>,E>> globalSeparatorList = new ArrayList<>();
  for (E e : graph.edgeSet()) {
    List<Pair<List<Pair<Integer,Integer>>,E>> separatorList = computeMinimalSeparatorList(e);
    globalSeparatorList.addAll(separatorList);
  }
  return globalSeparatorList;
}

private List<Pair<List<Pair<Integer,Integer>>,E>> computeGlobalSeparatorList(Graph graph) {
    List<Pair<List<Pair<Integer,Integer>>,E>> globalSeparatorList = new ArrayList<>();
    for (E e : graph.getEdges()) {
        List<Pair<Integer,Integer>> minimalSeparators = computeMinimalSeparators(graph, e);
        for (Pair<Integer,Integer> minimalSeparator : minimalSeparators) {
            globalSeparatorList.add(new Pair<>(minimalSeparator, e));
        }
    }
    return globalSeparatorList;
}

private List<Pair<List<Pair<Integer, Integer>>, E>> computeGlobalSeparatorList(Graph graph) {
    List<Pair<List<Pair<Integer, Integer>>, E>> result = new ArrayList<>();

    // Loop through all edges in the graph
    for (E edge : graph.edges()) {
        // Compute the minimal separators for the current edge
        List<Pair<Integer, Integer>> separatorList = computeMinimalSeparators(graph, edge);

        // Add the separators and edge to the result list
        result.add(new Pair<>(separatorList, edge));
    }

    return result;
}

public List<Pair<List<Pair<Integer, Integer>>, E>> computeGlobalSeparatorList(Graph G) {
    List<Pair<List<Pair<Integer, Integer>>, E>> result = new ArrayList<>();

    // For every edge e in the graph G = (V, E)
    for (Edge edge : G.getEdges()) {
        // Compute the list of minimal separators S_e in the neighborhood of e
        List<Pair<Integer, Integer>> separators = computeMinimalSeparators(G, edge);

        // Add the list of minimal separators for this edge to the result
        result.add(Pair.of(separators, edge));
    }

    return result;
}

private List<Pair<List<Pair<Integer, Integer>>, E>> computeGlobalSeparatorList() {
    List<Pair<List<Pair<Integer, Integer>>, E>> result = new ArrayList<>();
    for (E e : graph.edges()) {
        List<Pair<Integer, Integer>> minSeparators = getMinimalSeparators(e);
        for (Pair<Integer, Integer> separator : minSeparators) {
            result.add(Pair.of(separator, e));
        }
    }
    return result;
}

