public ByteVector putInt(int intValue) {
    // Enlarge the byte vector if necessary
    if (intValue < 0) {
        // If the int value is negative, we need to use 5 bytes to represent it
        ensureCapacity(getLength() + 5);
    } else {
        // If the int value is positive, we need to use 4 bytes to represent it
        ensureCapacity(getLength() + 4);
    }

    // Put the bytes of the int value into the byte vector
    for (int i = 0; i < 4; i++) {
        put((byte) (intValue >>> (8 * i)));
    }

    return this;
}

public ByteVector putInt(final int intValue) {
    // Resize the byte vector if necessary
    if (this.length + 4 > this.data.length) {
        int newLength = this.data.length;
        while (newLength < this.length + 4) {
            newLength = newLength * 2;
        }
        this.data = Arrays.copyOf(this.data, newLength);
    }

    // Put the int value into the byte vector
    this.data[this.length++] = (byte) (intValue >>> 24);
    this.data[this.length++] = (byte) (intValue >>> 16);
    this.data[this.length++] = (byte) (intValue >>> 8);
    this.data[this.length++] = (byte) intValue;

    return this;
}

public ByteVector putInt(final int intValue) {
    // Check if the byte vector needs to be enlarged
    if (this.data.length < this.wpos + 4) {
        int newSize = this.data.length * 2;
        while (newSize < this.wpos + 4) {
            newSize *= 2;
        }
        byte[] newData = new byte[newSize];
        System.arraycopy(this.data, 0, newData, 0, this.data.length);
        this.data = newData;
    }
    // Put the int into the byte vector
    this.data[this.wpos++] = (byte)(intValue >>> 24);
    this.data[this.wpos++] = (byte)(intValue >>> 16);
    this.data[this.wpos++] = (byte)(intValue >>> 8);
    this.data[this.wpos++] = (byte)intValue;
    return this;
}

public ByteVector putInt(final int intValue) {
    if (intValue >>> 7 == 0) {
        ensureCapacity(1);
        buffer[position++] = (byte) intValue;
    } else if (intValue >>> 14 == 0) {
        ensureCapacity(2);
        buffer[position++] = (byte) (intValue >>> 8);
        buffer[position++] = (byte) intValue;
    } else if (intValue >>> 21 == 0) {
        ensureCapacity(3);
        buffer[position++] = (byte) (intValue >>> 16);
        buffer[position++] = (byte) (intValue >>> 8);
        buffer[position++] = (byte) intValue;
    } else if (intValue >>> 28 == 0) {
        ensureCapacity(4);
        buffer[position++] = (byte) (intValue >>> 24);
        buffer[position++] = (byte) (intValue >>> 16);
        buffer[position++] = (byte) (intValue >>> 8);
        buffer[position++] = (byte) intValue;
    } else {
        ensureCapacity(5);
        buffer[position++] = (byte) (intValue >>> 32);
        buffer[position++] = (byte) (intValue >>> 24);
        buffer[position++] = (byte) (intValue >>> 16);
        buffer[position++] = (byte) (intValue >>> 8);
        buffer[position++] = (byte) intValue;
    }
    return this;
}

