  int numTypes = 0;
  for (int i = 0; i < descriptor.length(); i++) {
    switch (descriptor.charAt(i)) {
      case 'L': // Reference type.
        while (descriptor.charAt(i) != ';') {
          i++;
        }
        i++;
      case '[': // Array type.
        int arrayDims = 0;
        while (descriptor.charAt(i + arrayDims) == '[') {
          arrayDims++;
        }
        i += arrayDims;
        numTypes++;
        break;
      case 'V': // Void type.
      case 'Z': // Boolean type.
      case 'C': // Char type.
      case 'B': // Byte type.
      case 'S': // Short type.
      case 'I': // Int type.
      case 'F': // Float type.
      case 'D': // Double type.
      case 'J': // Long type.
        numTypes++;
        break;
      default:
        throw new AssertionError("Unknown type " + descriptor.charAt(i));
    }
  }
  // Pop the corresponding number of types from the stack.
  for (int i = 0; i < numTypes; i++) {
    stack.pop();
  }
}

