public static String applyRelativePath(String path, String relativePath) {
    // Check if the relative path is a file
    if (relativePath.startsWith(".")) {
        // If the relative path is a file, resolve the full file path
        return resolveFullPath(path + relativePath);
    } else {
        // If the relative path is a directory, resolve the full path and add the relative path as a suffix
        return resolveFullPath(path) + "/" + relativePath;
    }
}

public static String applyRelativePath(String path, String relativePath) {
    // First, split the relative path into its components
    String[] relativeComponents = relativePath.split("/");

    // Then, iterate over the components and check if they are absolute or relative
    for (String component : relativeComponents) {
        if (component.equals("..")) {
            // If the component is "..", remove the last segment from the path
            path = path.substring(0, path.lastIndexOf("/"));
        } else if (component.equals(".")) {
            // If the component is ".", do nothing
            continue;
        } else {
            // Otherwise, append the component to the path
            path += "/" + component;
        }
    }

    return path;
}

public static String applyRelativePath(String path, String relativePath) {

    // Split the relative path into its components
    String[] relativeComponents = relativePath.split("/");

    // Iterate over the components and update the path accordingly
    for (String component : relativeComponents) {
        if (component.equals(".")) {
            // Do nothing
        } else if (component.equals("..")) {
            // Go up one level
            int lastSeparatorIndex = path.lastIndexOf("/");
            if (lastSeparatorIndex != -1) {
                path = path.substring(0, lastSeparatorIndex);
            }
        } else {
            // Go down one level
            path = path + "/" + component;
        }
    }

    return path;
}

public static String applyRelativePath(String path, String relativePath) {
  // Validate inputs
  if (path == null || path.isEmpty()) {
    throw new IllegalArgumentException("Path cannot be null or empty");
  }
  if (relativePath == null || relativePath.isEmpty()) {
    throw new IllegalArgumentException("Relative path cannot be null or empty");
  }

  // Split the path and relative path into lists of folder names
  List<String> pathFolders = Arrays.asList(path.split("/"));
  List<String> relativePathFolders = Arrays.asList(relativePath.split("/"));

  // Resolve the relative path by removing or adding folders as necessary
  for (String folder : relativePathFolders) {
    if (folder.equals("..")) {
      // Remove the last folder from the path
      if (pathFolders.size() > 0) {
        pathFolders.remove(pathFolders.size() - 1);
      }
    } else {
      // Add the folder to the path
      pathFolders.add(folder);
    }
  }

  // Join the paths back together
  return String.join("/", pathFolders);
}

public static String applyRelativePath(String path, String relativePath) {
    // Replace any backslashes in the path with forward slashes
    path = path.replace("\\", "/");
    // Replace any backslashes in the relative path with forward slashes
    relativePath = relativePath.replace("\\", "/");
    // Split the path into its components, using forward slashes as separators
    String[] pathComponents = path.split("/");
    // Split the relative path into its components, using forward slashes as separators
    String[] relativePathComponents = relativePath.split("/");
    // Remove any empty strings from the end of the path components array
    while (pathComponents.length > 0 && pathComponents[pathComponents.length - 1].isEmpty()) {
        pathComponents = pathComponents.substring(0, pathComponents.length - 1);
    }
    // Remove any empty strings from the end of the relative path components array
    while (relativePathComponents.length > 0 && relativePathComponents[relativePathComponents.length - 1].isEmpty()) {
        relativePathComponents = relativePathComponents.substring(0, relativePathComponents.length - 1);
    }
    // If the relative path is not empty, loop through its components and modify the path accordingly
    for (String component : relativePathComponents) {
        if (component.equals(".")) {
            // If the component is ".", remove the last element from the path components array
            pathComponents = pathComponents.substring(0, pathComponents.length - 1);
        } else if (component.equals("..")) {
            // If the component is "..", remove the last two elements from the path components array
            pathComponents = pathComponents.substring(0, pathComponents.length - 2);
        } else {
            // If the component is a file or folder name, add it to the path components array
            pathComponents.push(component);
        }
    }
    // Join the path components array with forward slashes to form the new path
    return pathComponents.join("/");
}

