public List<ThreadSnapshot> parse(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
		List<ThreadSnapshot> snapshots = new ArrayList<ThreadSnapshot>();
		BufferedReader reader = null;
		try {
			reader = new BufferedReader(new FileReader(file));
			String line = null;
			while ((line = reader.readLine()) != null) {
				if (line.isEmpty()) {
					continue;
				}

				ThreadSnapshot snapshot = ThreadSnapshot.parse(line);
				if (snapshot == null) {
					continue;
				}

				long timestamp = snapshot.getTimestamp();
				if (timestamp == -1L) {
					timestamp = Long.parseLong(snapshot.getId().substring(0, snapshot.getId().indexOf('=')));
				}

				if (isInTimeRange(timestamp, timeRanges)) {
					snapshots.add(snapshot);
				}
			}
		} finally {
			if (reader != null) {
				reader.close();
			}
		}

		return snapshots;
	}

	private boolean isInTimeRange(long timestamp, List<ProfileAnalyzeTimeRange> timeRanges) {
		for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
			if (timestamp >= timeRange.getStart() && timestamp <= timeRange.getEnd()) {
				return true;
			}
		}
		return false;
	}
}

class ThreadSnapshot {
	private String id;
	private long timestamp;

	public ThreadSnapshot(String id, long timestamp) {
		this.id = id;
		this.timestamp = timestamp;
	}

	public String getId() {
		return id;
	}

	public long getTimestamp() {
		return timestamp;
	}

	public static ThreadSnapshot parse(String line) {
		String[] tokens = line.split("\\s+");
		if (tokens.length < 2) {
			return null;
		}

		String id = tokens[0];
		String timestampStr = tokens[1];
		long timestamp = -1L;
		try {
			timestamp = Long.parseLong(timestampStr);
		} catch (NumberFormatException e) {
			// ignore
		}

		return new ThreadSnapshot(id, timestamp);
	}
}

class ProfileAnalyzeTimeRange {
	private long start;
	private long end;

	public ProfileAnalyzeTimeRange(long start, long end) {
		this.start = start;
		this.end = end;
	}

	public long getStart() {
		return start;
	}

	public void setStart(long start) {
		this.start = start;
	}

	public long getEnd() {
		return end;
	}

	public void setEnd(long end) {
		this.end = end;
	}
}
